-- Up to three one-click next steps shown under a finished reply (generated by the server with a
-- small model right after the run completes).
alter table public.agent_runs
  add column suggestions jsonb
  check (suggestions is null or (jsonb_typeof(suggestions) = 'array' and jsonb_array_length(suggestions) <= 3));

comment on column public.agent_runs.suggestions is 'Next steps offered under the reply (array of up to 3 strings). Written by the server.';
